/**
 * One parsed SDCC-FLP (ST 1010.3 §6-§7). N×N symmetric: N std devs (diagonal) + N(N-1)/2
 * correlations (upper triangle, row-major).
 *
 * @param matrixSize {@code u64} (not {@code usize}) per the workspace's public-surface
 *     FFI-portability convention ({@code scripts/check/rust/no-public-usize.sh}) — a size/count
 *     field on a public struct must not vary shape across 32-/64-bit targets, even though typed KLV
 *     never crosses the C ABI today.
 * @param stdDevs Diagonal σ values, length == matrix_size (empty when Slen == 0).
 * @param correlations Upper-triangle correlations, row-major (i&lt;j), ABSENT slots as 0.0
 *     (sparse-mode zeros are reconstituted). Unlike {@code stdDevs}, this is ALWAYS the full {@code
 *     matrix_size*(matrix_size-1)/2} length regardless of {@code Clen} — a {@code Clen==0} pack (no
 *     correlation data at all) still gets a zero-filled vector of that length, not an empty one.
 *     Only empty when {@code matrix_size <= 1} (no possible correlation slots).
 * @param correlationPresent True where the wire actually carried the slot (all-true in full mode).
 */
public record SdccFlp(long matrixSize, double[] stdDevs, double[] correlations, boolean[] correlationPresent) {
// END GENERATED by print-records (SdccFlp)

    /**
     * &rho;(i,j) with symmetry; &sigma; via {@code stdDevs[i]} on the
     * diagonal. Pure-Java port of the Rust {@code SdccFlp::correlation}
     * (row-major upper-triangle index) — no JNI crossing needed.
     *
     * @param i row index, {@code 0 <= i < matrixSize}
     * @param j column index, {@code 0 <= j < matrixSize}
     * @return &rho;(i,j) off-diagonal, or &sigma;(i) on the diagonal
     * @throws IndexOutOfBoundsException if {@code i} or {@code j} is
     *         {@code >= matrixSize}, or on a diagonal query ({@code i == j})
     *         if this pack has no standard-deviation data at all
     *         ({@code Slen == 0} — spec-legal, see the {@link #stdDevs}
     *         field doc). Off-diagonal queries never hit that second case —
     *         {@link #correlations} is always sized to the full triangle
     *         regardless of {@code Clen}.
     */
    public double correlation(int i, int j) {
        long n = matrixSize;
        if (i < 0 || j < 0 || i >= n || j >= n) {
            throw new IndexOutOfBoundsException(
                    "SdccFlp.correlation index out of bounds: (" + i + ", " + j
                            + ") for matrixSize " + n);
        }
        if (i == j) {
            if (i >= stdDevs.length) {
                throw new IndexOutOfBoundsException(
                        "SdccFlp.correlation(" + i + ", " + i + "): no standard-deviation value "
                                + "available (Slen==0 / an empty stdDevs for this pack)");
            }
            return stdDevs[i];
        }
        int lo = Math.min(i, j);
        int hi = Math.max(i, j);
        int offset = lo * (2 * (int) n - lo - 1) / 2;
        return correlations[offset + (hi - lo - 1)];
    }
}
